/** 一个模板:网格模式直接存每格 RGB(0 = 留空),打开时建议的画幅边长 */
export class Tpl {
  name: string;
  grid: number[][];
  suggestedSize: number;

  constructor(name: string, suggestedSize: number, grid: number[][]) {
    this.name = name;
    this.suggestedSize = suggestedSize;
    this.grid = grid;
  }
}

/** 题材分类 */
export class Cat {
  name: string;
  items: Tpl[];

  constructor(name: string, items: Tpl[]) {
    this.name = name;
    this.items = items;
  }
}

/** 解析 "key:W:H:cells" 生成网格模板(同安卓 TemplateAssets.gridFromSpec) */
function gridFromSpec(name: string, suggestedSize: number, spec: string, master: BeadColor[]): Tpl {
  const p1: number = spec.indexOf(':');
  const p2: number = spec.indexOf(':', p1 + 1);
  const p3: number = spec.indexOf(':', p2 + 1);
  const w: number = parseInt(spec.substring(p1 + 1, p2), 10);
  const h: number = parseInt(spec.substring(p2 + 1, p3), 10);
  const cells: string = spec.substring(p3 + 1);

  const grid: number[][] = [];
  for (let y = 0; y < h; y++) {
    const row: number[] = new Array<number>(w).fill(0);
    grid.push(row);
  }
  const limit: number = Math.min(cells.length, w * h);
  for (let k = 0; k < limit; k++) {
    const code: number = cells.charCodeAt(k);
    if (code !== 46) {   // '.' = 留空
      grid[Math.floor(k / w)][k % w] = master[code - 35].rgb;
    }
  }
  return new Tpl(name, suggestedSize, grid);
}

/** Kenney 可爱系通用工厂(32x32 网格) */
function cuteCategory(title: string, specs: string[], names: string[], master: BeadColor[]): Cat {
  const list: Tpl[] = [];
  const count: number = Math.min(specs.length, names.length);
  for (let i = 0; i < count; i++) {
    list.push(gridFromSpec(names[i], 29, specs[i], master));
  }
  return new Cat(title, list);
}

/** Kenney Tiny Dungeon 萌系像素分类(36 个,16x16) */
function tinyCategory(master: BeadColor[]): Cat {
  const list: Tpl[] = [];
  const count: number = Math.min(TINY.length, TINY_NAMES.length);
  for (let i = 0; i < count; i++) {
    list.push(gridFromSpec(TINY_NAMES[i], 29, TINY[i], master));
  }
  return new Cat('🏰 迷你地牢', list);
}

/** 模板库全部分类(两级导航:先选分类,再看网格):
 *  🐾萌宠动物30 / 💬情绪气泡30 / 🏰迷你地牢36,同安卓 TemplateAssets.allCategories */
export function allCategories(palette: BeadColor[]): Cat[] {
  const cats: Cat[] = [];
  cats.push(cuteCategory('🐾 萌宠动物', CUTE_ANIMAL, CUTE_ANIMAL_NAMES, palette));
  cats.push(cuteCategory('💬 情绪气泡', CUTE_EMOTE, CUTE_EMOTE_NAMES, palette));
  cats.push(tinyCategory(palette));
  return cats;
}
